//! Build-time binding generation from the pinned Minecraft version data.
//!
//! ADG-3 decided that bindings are generated by reading the pinned client jar's
//! class files directly, and that nothing is written unless every reviewed hook
//! resolves exactly once, with the shape the inventory declares, from inputs
//! whose hashes match what is tracked. This is that generator.
//!
//! It reads its names two ways, because `cargo check --workspace` has to succeed
//! on a machine that does not hold the restricted client jar and most machines
//! do not. With the jar present it resolves against the class files and then
//! requires the result to be the tracked `mappings.lock` byte for byte, so drift
//! fails the build wherever the jar exists. With the jar absent it generates from
//! that same tracked lock, which already carries every name the jar resolved to,
//! and it first checks the lock against the hash `adapter.toml` pins for it, so
//! the jar-less path verifies a real pin rather than the lock against itself.
//! Either way the lock is what a build trusts, and the lock is tracked, so a
//! silent rename shows up in a diff.

mod classfile;
mod inputs;
mod jar;
mod render;
mod resolve;
mod stubs;

use std::fmt;
use std::fs;
use std::path::{Path, PathBuf};

/// The reading of the jar this generator performs, as recorded in the lock.
const EXTRACTOR: &str = "classfile";

/// Java class holding the generated native declarations.
const HOOK_CLASS: &str = "dev.ravel.jvm.Hook";

/// Library name `System.loadLibrary` resolves, without its platform decoration.
const LIBRARY: &str = "ravel_bootstrap";

/// Where the generated Java lands, relative to the repository root.
///
/// It is under `target/` because it is a build product: nothing there is
/// tracked, and nothing there is scanned for a hardcoded version string.
const JAVA_OUTPUT: &str = "target/ravel-jvm/generated/dev/ravel/jvm";

/// Where the generated compile-time stubs land, relative to the repository root.
///
/// They are a build product for the same reason `Hook.java` is, and they are
/// kept apart from it because nothing may ever package them: a stub inside a
/// shipped jar would shadow the game's own class on the loader they share.
const STUB_OUTPUT: &str = "target/ravel-jvm/generated-stubs";

/// Anything that stops a binding from being generated.
#[derive(Debug)]
pub enum GenerateError {
    /// An input is missing or unreadable.
    Input(String),
    /// An input's content does not match what is tracked.
    Drift(String),
    /// A hook entry does not resolve against the jar.
    Unresolved(String),
    /// An extractor could not read the jar.
    Extraction(String),
    /// A hook resolves, but its shape cannot be generated for.
    Unsupported(String),
}

impl fmt::Display for GenerateError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Input(detail) => write!(formatter, "an input is unusable: {detail}"),
            Self::Drift(detail) => write!(formatter, "an input drifted: {detail}"),
            Self::Unresolved(detail) => write!(formatter, "a hook does not resolve: {detail}"),
            Self::Extraction(detail) => write!(formatter, "extraction failed: {detail}"),
            Self::Unsupported(detail) => write!(formatter, "a hook cannot be generated: {detail}"),
        }
    }
}

impl std::error::Error for GenerateError {}

/// Everything one generation renders.
#[derive(Debug, Eq, PartialEq)]
struct Rendered {
    bindings: String,
    exports: String,
    hook_java: String,
    lock: String,
    stub_lock: String,
    /// Each stub's path below the stub tree, with its Java source.
    stub_java: Vec<(String, String)>,
}

/// What one generation produced.
#[derive(Debug)]
pub struct Generated {
    /// Files whose change has to re-run the generator.
    pub watched: Vec<PathBuf>,
    /// The Rust target table, for the adapter to include.
    pub bindings: PathBuf,
    /// The Rust JNI exports, for the bootstrap to include.
    pub exports: PathBuf,
    /// The generated Java hook class, for the agent jar build.
    pub java: PathBuf,
    /// Root of the generated compile-time stubs, for the screen jar build.
    pub stubs: PathBuf,
    /// Digest over every generated byte, independent of where it was written.
    pub sha256: String,
}

/// Rewrites `mappings.lock` and `stubs.lock` from the pinned jar.
///
/// Editing the reviewed inventory means the resolved set no longer matches what
/// the locks pin, and [`run`] refuses that drift by design. This is the
/// deliberate step that answers it, and it is deliberately separate: it resolves
/// against the pinned jar and writes what it found, so a lock can only be
/// rewritten by someone who has the jar and asked for it. The generator itself
/// still refuses to write one, which is what keeps drift an error rather than a
/// silent update.
///
/// # Errors
///
/// Returns an error when an input is missing or has drifted from the hash the
/// adapter inputs pin, when the pinned jar is absent, or when an inventory entry
/// does not resolve to exactly one member of the declared shape.
pub fn regenerate_locks(root: &Path) -> Result<(), GenerateError> {
    let pinned = inputs::pinned(root)?;
    let jar_path = root.join(&pinned.adapter.inputs.client_jar.path);
    let library_path = root.join(&pinned.adapter.inputs.data_fixer_jar.path);
    for (path, input) in [
        (&jar_path, &pinned.adapter.inputs.client_jar),
        (&library_path, &pinned.adapter.inputs.data_fixer_jar),
    ] {
        if !path.is_file() {
            return Err(GenerateError::Input(format!(
                "the pinned jar is absent at {}; a lock cannot be rewritten from another lock",
                input.path
            )));
        }
    }
    inputs::verify_input(root, &pinned.adapter.inputs.client_jar)?;
    inputs::verify_input(root, &pinned.adapter.inputs.data_fixer_jar)?;
    inputs::verify_input(root, &pinned.adapter.inputs.version_manifest)?;

    // Hook targets are game members, so they are resolved against the client jar
    // alone: a target that only the library declares would be a hook on something
    // the game does not own.
    let archive = jar::Archive::open(&jar_path)?;
    let library = jar::Archive::open(&library_path)?;
    let resolved = resolve::from_jar(&archive, &pinned.inventory)?;
    let stubbed = stubs::from_jar(&[&archive, &library], &pinned.seeds)?;

    write_atomically(
        &pinned.directory.join("mappings.lock"),
        &render::lock(&pinned.adapter, &resolved),
    )?;
    write_atomically(
        &pinned.directory.join("stubs.lock"),
        &render::stub_lock(&pinned.adapter, &stubbed),
    )?;
    // The locks and the hashes that pin them are rewritten together, because a
    // lock whose pin still describes the previous one is exactly the stale lock
    // this pin exists to catch.
    inputs::repin_locks(root, &pinned.directory, &pinned.adapter.inputs)
}

/// Generates every artefact of the pinned version into `out`.
///
/// # Errors
///
/// Returns an error when an input is missing, has drifted from the hash the
/// adapter inputs pin, does not resolve to exactly one member of the declared
/// shape, or resolves to a shape no hook can carry.
pub fn run(root: &Path, out: &Path) -> Result<Generated, GenerateError> {
    let pinned = inputs::pinned(root)?;
    let first = compose(root, &pinned)?;
    // ADG-3 requires generation to be reproducible, and the cheapest evidence of
    // that is doing it twice: a generator whose second run differs from its
    // first has read something it did not declare.
    if first != compose(root, &pinned)? {
        return Err(GenerateError::Drift(
            "generating twice produced different bytes".to_owned(),
        ));
    }
    write(root, out, &pinned, &first)
}

/// Resolves the pinned version and renders every artefact from it.
fn compose(root: &Path, pinned: &inputs::PinnedVersion) -> Result<Rendered, GenerateError> {
    let lock_path = pinned.directory.join("mappings.lock");
    let tracked = fs::read_to_string(&lock_path)
        .map_err(|error| GenerateError::Input(format!("cannot read mappings.lock: {error}")))?;

    let stub_path = pinned.directory.join("stubs.lock");
    let tracked_stubs = fs::read_to_string(&stub_path)
        .map_err(|error| GenerateError::Input(format!("cannot read stubs.lock: {error}")))?;

    // A machine without the jars has nothing to resolve against, so generating
    // from a lock and comparing the result back to that same lock only says the
    // file is well formed. These pins are what the jars produced, which is what
    // makes a stale lock fail here rather than pass a round trip against itself.
    inputs::verify_input(root, &pinned.adapter.inputs.mappings_lock)?;
    inputs::verify_input(root, &pinned.adapter.inputs.stubs_lock)?;

    let jar_path = root.join(&pinned.adapter.inputs.client_jar.path);
    let library_path = root.join(&pinned.adapter.inputs.data_fixer_jar.path);
    // Both jars or neither: a stub set read from half its sources would resolve
    // some seeds and not others, which is a different answer rather than a
    // fallback, and the lock is the one answer a machine without them trusts.
    let (resolved, stubbed) = if jar_path.is_file() && library_path.is_file() {
        inputs::verify_input(root, &pinned.adapter.inputs.client_jar)?;
        inputs::verify_input(root, &pinned.adapter.inputs.data_fixer_jar)?;
        inputs::verify_input(root, &pinned.adapter.inputs.version_manifest)?;
        let archive = jar::Archive::open(&jar_path)?;
        let library = jar::Archive::open(&library_path)?;
        (
            // Hook targets are game members and are never looked for in the
            // library jar.
            resolve::from_jar(&archive, &pinned.inventory)?,
            stubs::from_jar(&[&archive, &library], &pinned.seeds)?,
        )
    } else {
        (
            resolve::from_lock(&tracked, &pinned.adapter, &pinned.inventory)?,
            stubs::from_lock(&tracked_stubs, &pinned.adapter, &pinned.seeds)?,
        )
    };

    let lock = render::lock(&pinned.adapter, &resolved);
    if lock != tracked {
        return Err(GenerateError::Drift(
            "what resolved is not what mappings.lock pins; regenerate it deliberately".to_owned(),
        ));
    }
    let stub_lock = render::stub_lock(&pinned.adapter, &stubbed);
    if stub_lock != tracked_stubs {
        return Err(GenerateError::Drift(
            "what the seeds resolve to is not what stubs.lock pins; regenerate it deliberately"
                .to_owned(),
        ));
    }

    let shapes = render::shapes(&pinned.inventory, &resolved)?;
    let stub_java = stubbed
        .iter()
        .map(|stub| render::stub_java(&pinned.adapter, stub))
        .collect::<Result<Vec<_>, _>>()?;
    Ok(Rendered {
        bindings: render::bindings(&pinned.adapter, &pinned.inventory, &resolved),
        exports: render::exports(&shapes),
        hook_java: render::hook_java(&pinned.adapter, &shapes),
        lock,
        stub_lock,
        stub_java,
    })
}

/// Places every artefact, and reports what a build has to watch.
fn write(
    root: &Path,
    out: &Path,
    pinned: &inputs::PinnedVersion,
    rendered: &Rendered,
) -> Result<Generated, GenerateError> {
    let java_directory = root.join(JAVA_OUTPUT);
    let stub_directory = root.join(STUB_OUTPUT);
    for directory in [out, java_directory.as_path(), stub_directory.as_path()] {
        create(directory)?;
    }

    let bindings = out.join("bindings.rs");
    let exports = out.join("exports.rs");
    let java = java_directory.join("Hook.java");
    let mut digest = String::new();
    for (path, content) in [
        (&bindings, &rendered.bindings),
        (&exports, &rendered.exports),
        (&java, &rendered.hook_java),
    ] {
        write_atomically(path, content)?;
        digest.push_str(&inputs::sha256(content.as_bytes()));
        digest.push('\0');
    }
    for (relative, content) in &rendered.stub_java {
        let path = stub_directory.join(relative);
        if let Some(parent) = path.parent() {
            create(parent)?;
        }
        write_atomically(&path, content)?;
        digest.push_str(&inputs::sha256(content.as_bytes()));
        digest.push('\0');
    }

    let pins = &pinned.adapter.inputs;
    Ok(Generated {
        watched: vec![
            pinned.directory.join("adapter.toml"),
            pinned.directory.join("mappings.lock"),
            pinned.directory.join("stubs.lock"),
            root.join(&pins.hook_inventory.path),
            root.join(&pins.stub_seeds.path),
            root.join(&pins.client_jar.path),
            root.join(&pins.data_fixer_jar.path),
            root.join(&pins.version_manifest.path),
        ],
        bindings,
        exports,
        java,
        stubs: stub_directory,
        sha256: inputs::sha256(digest.as_bytes()),
    })
}

fn create(directory: &Path) -> Result<(), GenerateError> {
    fs::create_dir_all(directory).map_err(|error| {
        GenerateError::Input(format!("cannot create {}: {error}", directory.display()))
    })
}

/// Writes through a temporary name, so a generator that dies half way leaves
/// nothing behind that a build could pick up.
fn write_atomically(path: &Path, content: &str) -> Result<(), GenerateError> {
    let pending = path.with_extension(format!("pending{}", std::process::id()));
    fs::write(&pending, content).map_err(|error| {
        GenerateError::Input(format!("cannot write {}: {error}", path.display()))
    })?;
    fs::rename(&pending, path)
        .map_err(|error| GenerateError::Input(format!("cannot place {}: {error}", path.display())))
}

#[cfg(test)]
mod tests {
    use std::path::{Path, PathBuf};

    use super::{GenerateError, inputs, run};

    fn repository_root() -> &'static Path {
        Path::new(env!("CARGO_MANIFEST_DIR"))
            .ancestors()
            .nth(2)
            .expect("the crate lives under crates/<name>")
    }

    /// An output directory under the workspace's own build tree.
    ///
    /// It is under `target/` rather than the system temporary directory, so a
    /// run that fails part way cannot accumulate anywhere that matters, and it
    /// is scoped to the running process, because the tests run concurrently and
    /// a shared path would let one of them clear another's output mid-read.
    fn output(name: &str) -> PathBuf {
        let directory = repository_root()
            .join("target/ravel-generate-tests")
            .join(format!("{name}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&directory);
        directory
    }

    /// Copies the pinned version's tracked data into a root of its own.
    ///
    /// The copy holds no jars, which is the state of every machine that does not
    /// carry the restricted fixture, so generating in it takes the lock path.
    /// Returns the new root and its version directory.
    fn staged(name: &str) -> (PathBuf, PathBuf) {
        let root = output(name);
        // The version is read from the tracked data rather than written here, so
        // nothing outside the version data names a Minecraft version.
        let source = inputs::pinned(repository_root())
            .expect("the tracked version data should parse")
            .directory;
        let relative = source
            .strip_prefix(repository_root())
            .expect("the version data lives under the root");
        let directory = root.join(relative);
        std::fs::create_dir_all(&directory).expect("the staged version directory should be made");
        for entry in std::fs::read_dir(&source).expect("the tracked version data should be listed")
        {
            let file = entry.expect("a readable entry").file_name();
            std::fs::copy(source.join(&file), directory.join(&file)).expect("copyable");
        }
        (root, directory)
    }

    #[test]
    fn a_machine_without_the_jars_generates_from_a_lock_that_matches_its_pin() {
        let (root, _) = staged("jarless-honest");
        let out = output("jarless-honest-out");

        let generated = run(&root, &out).expect("an unedited lock still matches what is pinned");

        assert!(generated.bindings.is_file());

        let _ = std::fs::remove_dir_all(&root);
        let _ = std::fs::remove_dir_all(&out);
    }

    #[test]
    fn a_machine_without_the_jars_refuses_a_lock_that_no_longer_matches_its_pin() {
        let (root, directory) = staged("jarless-stale");
        let out = output("jarless-stale-out");
        // The lock's own bytes are left alone, so nothing but the pin can tell
        // this apart from the honest case: parsing the lock and rendering it back
        // still agrees with itself, which is the hole this pin closes.
        let adapter = directory.join("adapter.toml");
        let document = std::fs::read_to_string(&adapter).expect("readable");
        let length = std::fs::metadata(directory.join("mappings.lock"))
            .expect("the staged lock should be there")
            .len();
        let stale =
            inputs::replace_pin(&document, "[inputs.mappingsLock]", &"0".repeat(64), length)
                .expect("the staged adapter inputs pin the lock");
        assert_ne!(stale, document, "the pin has to actually be made stale");
        std::fs::write(&adapter, stale).expect("writable");

        let error =
            run(&root, &out).expect_err("a lock that is not what is pinned must be refused");

        assert!(matches!(error, GenerateError::Drift(_)), "{error}");
        let message = error.to_string();
        assert!(message.contains("mappings.lock"), "{message}");
        assert!(message.contains("the adapter inputs pin"), "{message}");

        let _ = std::fs::remove_dir_all(&root);
        let _ = std::fs::remove_dir_all(&out);
    }

    #[test]
    fn generating_from_the_tracked_inputs_writes_every_artefact() {
        let out = output("artefacts");

        let generated = run(repository_root(), &out).expect("the tracked inputs should generate");

        assert!(generated.bindings.is_file());
        assert!(generated.exports.is_file());
        assert!(generated.java.is_file());
        assert_eq!(generated.sha256.len(), 64);
        assert_eq!(generated.watched.len(), 8);

        let screen = generated
            .stubs
            .join("net/minecraft/client/gui/screens/Screen.java");
        let stub = std::fs::read_to_string(&screen).expect("the seeded class should be stubbed");
        assert!(
            stub.contains("package net.minecraft.client.gui.screens;"),
            "{stub}"
        );
        assert!(stub.contains("class Screen"), "{stub}");
        assert!(
            !stub.contains("extends net.minecraft.client.gui.components"),
            "nothing above Screen is stubbed, so the stub declares nothing above it: {stub}"
        );

        let bindings = std::fs::read_to_string(&generated.bindings).expect("readable");
        assert!(bindings.contains("pub static TARGETS"));
        assert!(bindings.contains("HookKind::InstanceField"));

        let exports = std::fs::read_to_string(&generated.exports).expect("readable");
        assert!(exports.contains("jni_mangle"));
        assert!(
            !exports.contains("lastAmount"),
            "a field is not a call target and gets no export"
        );

        let java = std::fs::read_to_string(&generated.java).expect("readable");
        assert!(java.contains("System.loadLibrary(LIBRARY);"));
        assert!(java.contains("public static native long nativeInvocations();"));
        // The screen's two crossings are declared on this class and nowhere
        // else: ADG-1 gives Ravel one exported symbol surface, so a screen that
        // declared its own natives would be a second one.
        assert!(java.contains("public static native String ravelSettingsDocument(String owner);"));
        assert!(java.contains("public static native String ravelSaveSettings(String payload);"));
        assert!(java.contains("public static native String ravelModSurface();"));
        assert!(java.contains("public static native void ravelEnableProfiling(String value);"));
        assert!(java.contains("public static native String ravelProfilingReport();"));

        let _ = std::fs::remove_dir_all(&out);
    }

    #[test]
    fn generation_is_reproducible_byte_for_byte() {
        let root = repository_root();
        let first = output("once");
        let second = output("twice");

        let one = run(root, &first).expect("generates");
        let two = run(root, &second).expect("generates");

        assert_eq!(one.sha256, two.sha256);
        for (left, right) in [(&one.bindings, &two.bindings), (&one.exports, &two.exports)] {
            assert_eq!(
                std::fs::read_to_string(left).expect("readable"),
                std::fs::read_to_string(right).expect("readable")
            );
        }

        for directory in [&first, &second] {
            let _ = std::fs::remove_dir_all(directory);
        }
    }

    #[test]
    fn a_root_without_version_data_generates_nothing() {
        let error = run(Path::new("/nonexistent-ravel-root"), Path::new("/tmp"))
            .expect_err("there is nothing to generate from");

        assert!(matches!(error, GenerateError::Input(_)));
        assert!(error.to_string().starts_with("an input is unusable"));
    }

    #[test]
    fn every_refusal_says_what_kind_of_refusal_it_is() {
        for (error, expected) in [
            (GenerateError::Input(String::new()), "an input is unusable"),
            (GenerateError::Drift(String::new()), "an input drifted"),
            (
                GenerateError::Unresolved(String::new()),
                "a hook does not resolve",
            ),
            (
                GenerateError::Extraction(String::new()),
                "extraction failed",
            ),
            (
                GenerateError::Unsupported(String::new()),
                "a hook cannot be generated",
            ),
        ] {
            assert!(error.to_string().starts_with(expected), "{error}");
        }
    }
}
